int
device_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
               int *eofp, caller_context_t *ct_unused, int flags_unused)
{
    int error = 0;
    struct dirent *dent = NULL;
    off_t offset = uiop->uio_offset;
    size_t remaining = uiop->uio_resid;

    if (remaining < sizeof(struct dirent)) {
        *eofp = 1;
        return 0;
    }

    dent = (struct dirent *)malloc(sizeof(struct dirent));
    if (dent == NULL) {
        return ENOMEM;
    }

    if (strncmp(dvp->v_name, ZVOL_DIR, strlen(ZVOL_DIR)) == 0) {
        if (offset == 0) {
            strcpy(dent->d_name, ".");
            dent->d_fileno = 1;
            dent->d_type = DT_DIR;
            dent->d_namlen = 1;
        } else if (offset == 1) {
            strcpy(dent->d_name, "..");
            dent->d_fileno = 2;
            dent->d_type = DT_DIR;
            dent->d_namlen = 2;
        } else {
            size_t idx = offset - 2;
            struct dataset *ds;

            if (idx >= MAX_DATASETS) {
                error = EINVAL;
                goto out;
            }

            ds = &datasets[idx];
            if (ds->name[0] == '\0') {
                *eofp = 1;
                error = 0;
                goto out;
            }

            strncpy(dent->d_name, ds->name, MAX_NAME_LEN);
            dent->d_namlen = strlen(ds->name);
            dent->d_type = DT_DIR;
            dent->d_fileno = offset;
        }
    } else {
        error = ENOTDIR;
        goto out;
    }

    dent->d_reclen = sizeof(struct dirent) + dent->d_namlen;

    error = uiomove(dent, dent->d_reclen, uiop);
    if (error != 0) {
        goto out;
    }

    offset++;
    *eofp = (offset >= MAX_ENTRIES) ? 1 : 0;
    uiop->uio_offset = offset;

out:
    free(dent);
    return error;
}

int
device_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
               int *eofp, caller_context_t *ct_unused, int flags_unused)
{
    int error = 0;
    struct dirent *dent;
    char *name;
    off_t pos;

    *eofp = 0;

    while (uiop->uio_resid >= sizeof(struct dirent)) {
        dent = (struct dirent *)uiop->uio_iov->iov_base;
        name = dent->d_name;

        if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0) {
            /* Skip current and parent directory entries */
            continue;
        }

        if (strncmp(dvp->v_path, ZVOL_DIR, strlen(ZVOL_DIR)) == 0) {
            /* Handle special directory entries under ZVOL_DIR */
            if (strcmp(name, "snapshots") == 0) {
                strcpy(dent->d_name, "snapshots");
                dent->d_type = DT_DIR;
                dent->d_namlen = strlen("snapshots");
                dent->d_fileno = 0; /* Placeholder for a real file number */
                dent->d_reclen = sizeof(struct dirent) + dent->d_namlen;
                uiop->uio_iov->iov_base += dent->d_reclen;
                uiop->uio_iov->iov_len -= dent->d_reclen;
                uiop->uio_offset += dent->d_reclen;
                continue;
            }

            /* Iterate over datasets and populate directory entries */
            if (create_dir_entry_from_dataset(dent, name, dvp->v_path)) {
                continue;
            }
        }

        /* End of directory or no more entries */
        *eofp = 1;
        error = 0;
        break;
    }

    if (uiop->uio_resid < sizeof(struct dirent)) {
        *eofp = 1;
        error = 0;
    }

    return error;
}

int readdir_dev_vnode(struct vnode *dvp, struct uio *uiop, struct cred *cred,
                      int *eofp, caller_context_t *ct_unused, int flags_unused) {
    int error = 0;
    *eofp = 0;

    if (strcmp(dvp->v_path, ZVOL_DIR) == 0) {
        struct dirent *dent = NULL;
        size_t namelen;
        off_t offset = uiop->uio_offset;
        size_t i;

        for (i = 0; i < dataset_count; i++) {
            namelen = strlen(datasets[i].name);
            if (offset >= (i + 1) * (sizeof(struct dirent) + namelen))
                continue;

            dent = (struct dirent *)malloc(sizeof(struct dirent) + namelen);
            if (!dent) {
                error = ENOMEM;
                break;
            }

            dent->d_ino = datasets[i].ino;
            dent->d_type = DT_DIR;
            dent->d_namlen = namelen;
            memcpy(dent->d_name, datasets[i].name, namelen);

            error = uiomove(dent, sizeof(struct dirent) + namelen, uiop);
            free(dent);
            if (error)
                break;

            offset += sizeof(struct dirent) + namelen;
        }

        if (i >= dataset_count)
            *eofp = 1;
    } else {
        error = ENOTDIR;
    }

    return error;
}

int
device_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
    int *eofp, caller_context_t *ct_unused, int flags_unused)
{
	struct dirent *dent;
	int error = 0;
	off_t offset;
	char *dir_path;

	/* Initialize variables */
	*eofp = 0;
	dent = NULL;
	dir_path = NULL;

	/* Check for special cases like ZVOL_DIR */
	if (strcmp(dvp->v_name, ZVOL_DIR) == 0) {
		/* Create necessary directories if not exist */
		if ((error = create_zvol_directories()) != 0)
			goto out;
	}

	/* Iterate over datasets and populate directory entries */
	for (offset = uiop->uio_offset; ; offset += sizeof(*dent)) {
		dent = (struct dirent *)malloc(sizeof(*dent));
		if (dent == NULL) {
			error = ENOMEM;
			goto out;
		}

		memset(dent, 0, sizeof(*dent));
		dent->d_fileno = get_next_dataset_id();
		dent->d_namlen = strlen("dataset");
		strcpy(dent->d_name, "dataset");

		error = uiomove(dent, sizeof(*dent), uiop);
		if (error != 0)
			goto out;

		if (uiop->uio_resid == 0) {
			*eofp = 1;
			break;
		}
	}

out:
	if (dent)
		free(dent);
	if (dir_path)
		free(dir_path);

	return error;
}
